INSERT INTO public.doctor_posts (id, created_at, updated_at, author_id, disease_name, clinical_findings, diagnosis, treatment_plan, drugs_used, specialty_tags, poll_question, poll_options, is_urgent, quoted_post_id) VALUES ('82df937f-b20d-4d76-939e-140d47d4725e', '2026-09-26 17:23:10.724979', '2026-09-27 10:42:23.158747', 'dd7d2ebf-797c-4f88-adcd-aa8923f075f3', 'Severe Refractory Dengue with Secondary HLH (Hemophagocytic Syndrome)', '28M returned from travel 9 days prior with fever, severe retro-orbital headache, and myalgias. Transferred to ICU on Day 8 in hyperinflammatory shock. Labs: Hemoglobin 7.4 g/dL, Platelets 14,000/mcL, Absolute Neutrophil Count 380/mcL. Serum Ferritin > 42,000 ng/mL, Triglycerides 510 mg/dL, Fibrinogen 88 mg/dL. Bone marrow aspirate confirmed active hemophagocytosis of erythroblasts by activated macrophages.', 'Severe Secondary Hemophagocytic Lymphohistiocytosis (HLH / MAS) triggered by acute Dengue Virus (DENV-2 serotype).', 'Patient managed in Medical ICU with protective ventilation and invasive arterial monitoring. Dexamethasone 10 mg/m² daily instituted immediately per HLH-2004 modified guidelines. Concomitant IVIG 1 g/kg/day for 2 days. Platelets transfused to maintain > 20k with cryoprecipitate for fibrinogen > 150 mg/dL. Requesting multidisciplinary input from Hematology on early Etoposide introduction vs Anakinra (IL-1 antagonist).', '["Dexamethasone 10mg/m2", "IVIG 1g/kg", "Cryoprecipitate", "Platelet Apheresis", "N-Acetylcysteine"]', '["Infectious Disease", "Critical Care", "Hematology", "Surveillance"]', 'Preferred management for hyperinflammatory cytokine storm in viral HLH?', '["Anakinra (Early IL-1 Blockade)", "Modified Etoposide Protocol", "High-Dose Dexamethasone monotherapy", "Therapeutic Plasma Exchange (TPE)"]', true, NULL);
INSERT INTO public.doctor_posts (id, created_at, updated_at, author_id, disease_name, clinical_findings, diagnosis, treatment_plan, drugs_used, specialty_tags, poll_question, poll_options, is_urgent, quoted_post_id) VALUES ('95aa1af5-bcf1-44ba-ba5a-1ac1813a4a37', '2026-09-26 13:23:10.728441', '2026-09-27 10:42:23.158747', '4fb80e8c-fc90-48e9-9da9-c1caa606d4ae', 'Toxic Epidermal Necrolysis (TEN) Induced by Allopurinol (HLA-B*58:01)', '63M with gout who initiated allopurinol 100 mg 3 weeks ago. Presented with painful coalescent dusky erythematous macules on face and trunk that rapidly evolved into extensive flaccid bullae with positive Nikolsky sign, peeling in sheet-like fashion over 40% Total Body Surface Area (TBSA). Severe stomatitis, conjunctival purulence, and genital erosions. SCORTEN score: 3 (predicted in-hospital mortality 35.3%).', 'Toxic Epidermal Necrolysis (TEN) — Severe Cutaneous Adverse Reaction (SCAR) secondary to allopurinol in HLA-B*58:01 carrier.', 'Immediate cessation of allopurinol and all non-vital medications. Emergent transfer to specialized Burn ICU with 32°C ambient thermal control. Non-adherent silicone foam dressing applied without aggressive debridement. High-dose IVIG (1 g/kg/day x 3 days) combined with early oral Cyclosporine (3 mg/kg/day for 10 days). Daily ophthalmologic assessment with amniotic membrane transplantation consideration.', '["IVIG 1g/kg/day", "Cyclosporine 3mg/kg/day", "Hartmann Solution Resuscitation", "Mupirocin Ointment"]', '["Dermatology", "Allergy & Immunology", "Critical Care", "Pharmacology"]', 'Recommended systemic adjuvant immunomodulator in acute TEN?', '["Oral Cyclosporine (3mg/kg/day)", "High-Dose IVIG monotherapy", "Etanercept (50mg SC)", "High-dose systemic corticosteroids"]', true, NULL);
INSERT INTO public.doctor_posts (id, created_at, updated_at, author_id, disease_name, clinical_findings, diagnosis, treatment_plan, drugs_used, specialty_tags, poll_question, poll_options, is_urgent, quoted_post_id) VALUES ('9acd08e7-62ae-4faf-8114-95d541f6bb03', '2026-09-27 01:23:10.710549', '2026-09-27 10:42:23.158747', '7fa23e69-2803-4d8a-8301-d8cb9dda4b3a', 'Anti-NMDA Receptor Encephalitis in a Young Female', '22F university student presenting with acute progressive neuropsychiatric decompensation: auditory hallucinations, paranoia, hyperverbal speech progressing over 10 days to severe catatonia, autonomic instability, and stereotypic orofacial dyskinesias. Lumbar puncture revealed CSF lymphocytic pleocytosis (42 cells/mcL), elevated IgG index, and positive Anti-GluN1 antibodies. Continuous EEG captured classic ''extreme delta brush'' pattern.', 'Autoimmune Anti-NMDA Receptor Encephalitis secondary to an occult ovarian teratoma.', 'Pelvic MRI confirmed 3.4 cm mature cystic ovarian teratoma. Laparoscopic cystectomy performed on hospital day 3. First-line dual immunotherapy initiated: IV Methylprednisolone 1,000 mg daily for 5 days alongside high-dose IVIG (2 g/kg total dose over 5 days). Second-line therapy with Rituximab (375 mg/m² weekly x 4) added due to refractory dyskinesias. Patient demonstrated substantial cognitive recovery by week 4.', '["Methylprednisolone 1g IV", "Intravenous Immunoglobulin (IVIG)", "Rituximab", "Levetiracetam 1000mg BID"]', '["Neurology", "Immunology", "Psychiatry", "Critical Care"]', 'Optimal second-line immunotherapy strategy for refractory encephalitis?', '["Rituximab (Anti-CD20) infusion", "Cyclophosphamide pulse", "Tocilizumab (IL-6 receptor antagonist)", "Bortezomib (Proteasome inhibitor)"]', false, NULL);
INSERT INTO public.doctor_posts (id, created_at, updated_at, author_id, disease_name, clinical_findings, diagnosis, treatment_plan, drugs_used, specialty_tags, poll_question, poll_options, is_urgent, quoted_post_id) VALUES ('b8d2d2a9-9f44-433f-ad36-c1a5a2765e36', '2026-09-26 21:23:10.712571', '2026-09-27 10:42:23.158747', 'ec0331a4-43ea-4bcf-93ef-fc38a06aa25b', 'Atypical Kawasaki Disease with Early Coronary Ectasia', '3.5-year-old boy presenting with persistent high-grade remittent fever (39.5°C) for 6 days refractory to oral cephalosporins. Examination shows non-purulent bilateral bulbar conjunctival injection, dry cracked lips with classic strawberry tongue, cervical lymphadenopathy (1.8 cm right anterior chain), and indurated palmar erythema with periungual desquamation. Transthoracic echo revealed early dilation of the proximal Right Coronary Artery (RCA Z-score +3.6).', 'Incomplete / Atypical Kawasaki Disease complicated by acute coronary arteritis.', 'Administered single high-dose IVIG (2 g/kg infused over 12 hours) within the 10-day therapeutic window. Started high-dose oral Aspirin (80 mg/kg/day divided into 4 doses) until patient remained afebrile for 48 hours, followed by low-dose antiplatelet Aspirin (5 mg/kg/day once daily for 8 weeks). Repeat echocardiography at 2 weeks demonstrated regression of coronary lumen Z-score to +1.8.', '["Intravenous Immunoglobulin 2g/kg", "Aspirin 80mg/kg/day", "Aspirin 5mg/kg/day"]', '["Pediatrics", "Cardiology", "Rheumatology", "SpotDiagnosis"]', 'Next-line protocol if toddler remains febrile 48h post-IVIG?', '["Second dose IVIG (2g/kg)", "Infliximab (TNF-alpha blockade)", "Pulse Methylprednisolone (30mg/kg)", "Anakinra (IL-1 receptor antagonist)"]', false, NULL);
INSERT INTO public.doctor_posts (id, created_at, updated_at, author_id, disease_name, clinical_findings, diagnosis, treatment_plan, drugs_used, specialty_tags, poll_question, poll_options, is_urgent, quoted_post_id) VALUES ('e4c8a60b-2e64-484d-b47d-e5509f6a9231', '2026-09-27 05:23:10.612143', '2026-09-27 10:42:23.158747', 'cb6b5947-1bbf-4011-bc52-b60479b10993', 'Wellens'' Syndrome (Type A Biphasic T-Waves in LAD Stenosis)', '54M presented with episodic severe retrosternal chest tightness lasting 30 minutes, now completely pain-free upon arrival. Vitals: BP 136/82, HR 74, SpO2 98% room air. Initial Troponin I is 0.04 ng/mL (borderline). 12-lead ECG during the pain-free window reveals pathognomonic biphasic T-waves in leads V2 and V3 without ST-segment elevation and no loss of precordial R-waves.', 'Wellens'' Syndrome Type A — Critical proximal Left Anterior Descending (LAD) coronary artery stenosis with high imminent risk of extensive anterior wall myocardial infarction.', 'Patient admitted straight to CCU. Absolute contraindication to treadmill exercise testing (provokes sudden fatal anterior STEMI). Initiated DAPT (Aspirin 325 mg + Ticagrelor 180 mg loading) and therapeutic IV Unfractionated Heparin infusion. Emergent cardiac catheterization performed within 2.5 hours revealed 95% critical stenosis in proximal LAD. Successful deployment of a drug-eluting stent (DES) with TIMI 3 flow restored.', '["Aspirin 325mg", "Ticagrelor 180mg", "Unfractionated Heparin", "Atorvastatin 80mg", "Metoprolol Succinate 25mg"]', '["Cardiology", "Emergency Medicine", "Critical Care", "ECG"]', 'What is the immediate priority intervention for Wellens Syndrome Type A?', '["Emergent Invasive Coronary Catheterization (PCI)", "Conservative CCU Monitoring & Echo", "Treadmill Stress Test (Contraindicated)", "High-Dose Statin & Discharge"]', true, NULL);
INSERT INTO public.doctor_posts (id, created_at, updated_at, author_id, disease_name, clinical_findings, diagnosis, treatment_plan, drugs_used, specialty_tags, poll_question, poll_options, is_urgent, quoted_post_id) VALUES ('853fbb8c-f88d-4cd1-8942-d281d0e865b6', '2026-09-27 13:17:24.911049', '2026-09-27 13:17:24.911049', 'b9f14389-37bf-4d51-91ac-3fd6df18ffab', 'Comparative Management: Severe Refractory Dengue with Secondary HLH (Hemophagocytic Syndrome)', 'Evaluating institutional variance and early revascularization timing across centers.', 'Institutional Review of Severe Secondary Hemophagocytic Lymphohistiocytosis (HLH / MAS) triggered by acute Dengue Virus (DENV-2 serotype).', 'Alternative Tier-1 protocol: Early invasive catheterization within 12h combined with parenteral Cangrelor bridge.', '["Cangrelor", "Aspirin", "Bivalirudin"]', '["Cardiology", "QuoteCase", "ClinicalAudit"]', NULL, '[]', false, '82df937f-b20d-4d76-939e-140d47d4725e');
INSERT INTO public.doctor_posts (id, created_at, updated_at, author_id, disease_name, clinical_findings, diagnosis, treatment_plan, drugs_used, specialty_tags, poll_question, poll_options, is_urgent, quoted_post_id) VALUES ('a4267fa6-0874-41a1-9485-caab09e9e018', '2026-09-27 13:27:13.771535', '2026-09-27 13:27:13.771535', '903c2fee-d0b7-405c-b627-9bdfa3bd2f51', 'Institutional Protocol: Comparative Management: Severe Refractory Dengue with Secondary HLH (Hemophagocytic Syndrome)', 'Institutional cohort comparative study. Presentation mirrors the quoted index case.', 'Confirmed Comparative Management: Severe Refractory Dengue with Secondary HLH (Hemophagocytic Syndrome) under ESC/AHA criteria', 'First-line dual antiplatelet therapy + immediate interventional catheterization.', '["Aspirin 325mg", "Ticagrelor 180mg", "Unfractionated Heparin"]', '["ComparativeProtocol", "Cardiology", "Consensus"]', NULL, '[]', false, '853fbb8c-f88d-4cd1-8942-d281d0e865b6');
INSERT INTO public.doctor_posts (id, created_at, updated_at, author_id, disease_name, clinical_findings, diagnosis, treatment_plan, drugs_used, specialty_tags, poll_question, poll_options, is_urgent, quoted_post_id) VALUES ('4d727300-e19e-4441-be18-ce99a8798e75', '2026-09-27 13:44:50.889634', '2026-09-27 13:44:50.889634', '903c2fee-d0b7-405c-b627-9bdfa3bd2f51', 'Institutional Protocol: Institutional Protocol: Comparative Management: Severe Refractory Dengue with Secondary HLH (Hemophagocytic Syndrome)', 'Institutional cohort comparative study. Presentation mirrors the quoted index case.', 'Confirmed Institutional Protocol: Comparative Management: Severe Refractory Dengue with Secondary HLH (Hemophagocytic Syndrome) under ESC/AHA criteria', 'First-line dual antiplatelet therapy + immediate interventional catheterization.', '["Aspirin 325mg", "Ticagrelor 180mg", "Unfractionated Heparin"]', '["ComparativeProtocol", "Cardiology", "Consensus"]', NULL, '[]', false, 'a4267fa6-0874-41a1-9485-caab09e9e018');


